using System.IO;
using System.Text.Json;namespace OdinVault.Manager.Wpf.Services;internal sealed record ManagerSettings(bool StartMinimizedToTray=false,bool MinimizeToTray=true,bool ShowTrayNotifications=true,bool CheckForUpdatesOnStart=true,string Theme="Light",string Language="fa");internal sealed class ManagerSettingsStore{static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web){WriteIndented=true};readonly string path;public ManagerSettingsStore(){var d=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OdinVault");Directory.CreateDirectory(d);path=Path.Combine(d,"manager-settings.json");}public ManagerSettings Load(){try{return File.Exists(path)?JsonSerializer.Deserialize<ManagerSettings>(File.ReadAllText(path),Json)??new():new();}catch{return new();}}public void Save(ManagerSettings s){s=s with{Theme=s.Theme.Equals("Dark",StringComparison.OrdinalIgnoreCase)?"Dark":"Light",Language=s.Language.Equals("en",StringComparison.OrdinalIgnoreCase)?"en":"fa"};var t=path+".tmp";File.WriteAllText(t,JsonSerializer.Serialize(s,Json));File.Move(t,path,true);}}